"""If changed node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ... import saved_values as saved
from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError


class IfChangedNode(Node):
    """Compares a value with last time, saves it, then goes Changed or No change."""

    node_type: ClassVar[str] = 'if_changed_node'
    display_name: ClassVar[str] = 'If changed'
    default_alias: ClassVar[str] = 'If changed'
    description: ClassVar[str] = 'Compares a value with last time, saves it, then goes Changed or No change'
    category: ClassVar[str] = NodeCategory.DATA
    primary_family: ClassVar[str] = 'Utility'
    tags: ClassVar[List[str]] = ['Saved values', 'across runs']
    icon_name: ClassVar[str] = 'git-compare'
    color_hint: ClassVar[str] = 'grey'
    group: ClassVar[Optional[str]] = 'Saved values'
    selector_section: ClassVar[Optional[str]] = 'Saved values'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['changed', 'no_change']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Value', 'description': 'The value to compare and save', 'data_type': 'any', 'required': True, 'sources': ['upstream', 'vault']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'changed': {'name': 'Changed', 'description': 'The new value', 'data_type': 'any', 'required': False, 'to': ['downstream']}, 'no_change': {'name': 'No change', 'description': 'The value, the same as last time', 'data_type': 'any', 'required': False, 'to': ['downstream']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Upstream payload', 'input_vault_key': '', 'name': '', 'keep_for': 'This workflow', 'compare': 'Exactly', 'first_time': 'No change', 'if_not_saved': 'Stop with an error', 'changed_label': '', 'no_change_label': '', 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': []}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Value source', 'options': ['Upstream payload', 'Vault'], 'tab': 'Source', 'section': 'Required Inputs', 'description': 'The value to compare and save'}, 'input_vault_key': {'type': 'string', 'label': 'Value Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'any', 'visible_when': {'input_source': 'Vault'}}, 'name': {'type': 'string', 'label': 'Saved as', 'required': True, 'placeholder': 'a name, like last_version', 'tab': 'Parameters'}, 'keep_for': {'type': 'select', 'label': 'Kept for', 'options': [['This workflow · only this workflow sees it', 'This workflow'], ['All workflows · shared on this machine', 'All workflows']], 'tab': 'Parameters'}, 'compare': {'type': 'select', 'label': 'Compare', 'options': [['Exactly', 'Exactly'], ['Ignore spaces and capitals', 'Loosely']], 'tab': 'Parameters'}, 'first_time': {'type': 'select', 'label': 'First run (nothing saved yet)', 'options': [['No change · save quietly', 'No change'], ['Changed · send it on', 'Changed']], 'tab': 'Parameters'}, 'if_not_saved': {'type': 'select', 'label': "If it can't be saved", 'options': [['Stop · the node fails', 'Stop with an error'], ['Carry on · take No change', 'Carry on']], 'tab': 'Parameters'}, 'changed_label': {'type': 'string', 'label': 'Changed path name', 'placeholder': 'shown on the map; blank = Changed', 'tab': 'Parameters'}, 'no_change_label': {'type': 'string', 'label': 'No change path name', 'placeholder': 'shown on the map; blank = No change', 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'store_unwritable', 'description': 'The saved values file could not be written.', 'retryable': True}, {'code': 'store_unreadable', 'description': 'The saved values file could not be read.', 'retryable': True}, {'code': 'too_big', 'description': 'The value is over 64 KB, or is not plain data.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        try:
            value = saved.node_value(self, context)
        except ValueError as exc:
            context.signal_error(exc)
            return
        place = saved.place_for(self.config.get("keep_for"), context.workflow_name)
        try:
            changed, _previous = saved.SavedValues().check_and_save(
                place, self.config.get("name"), value, saved.saved_by(context),
                loosely=self.config.get("compare") == "Loosely")
        except saved.SavedValuesError as exc:
            if self.config.get("if_not_saved") != "Carry on":
                context.signal_error(NodeError(exc.code, str(exc), retryable=exc.code in saved.RETRYABLE))
                return
            changed = False
        if changed is None:  # first run: nothing was saved yet
            changed = self.config.get("first_time") == "Changed"
        port = "changed" if changed else "no_change"
        data = {port: value} if self.config.get("transient_output", True) else {}
        context.signal_done({"data": data, "output_port": port, "next_node_id": None})
